class OlAsyncIOScheduler(_OlScheduler, AsyncIOScheduler):
    """Asyncio scheduler with monitoring listeners and stable job IDs."""


def job_listener(event: JobEvent):
    if event.code == EVENT_JOB_SUBMITTED:
        print(f"Job {event.job_id} has started.", flush=True)
    elif event.code == EVENT_JOB_EXECUTED:
        print(f"Job {event.job_id} completed successfully.", flush=True)
    elif event.code == EVENT_JOB_ERROR:
        print(f"Job {event.job_id} failed.", flush=True)


def bash_run(cmd: str, sources: list[str] | None = None, capture_output=False):
    if not sources:
        sources = []

    source_paths = [
        (
            os.path.join("scripts", "monitoring", source)
            if not os.path.isabs(source)
            else source
        )
        for source in sources
    ]
    bash_command = "\n".join(
        (
            'set -e',
            *(f'source "{path}"' for path in source_paths),
            cmd,
        )
    )


def get_service_ip(image_name: str) -> str:
    """Return the IP address of a running Docker container by name or image."""
    result = subprocess.run(
        ["docker", "inspect", image_name], check=True, capture_output=True, text=True
    )
    containers = json.loads(result.stdout)
    if not containers:
        raise ValueError(f"No container found for {image_name}")
    network_settings = containers[0].get("NetworkSettings", {})
    ip_address = network_settings.get("IPAddress")
    if not ip_address:
        ip_address = next(
            (
                network.get("IPAddress")
                for network in network_settings.get("Networks", {}).values()
                if network.get("IPAddress")
            ),
            None,
        )
    if not ip_address:
        raise ValueError(f"No IP address found for container {image_name}")
    return ip_address

    return subprocess.run(
        [
            "bash",
            "-c",
            bash_command,
        ],
        check=True,
        # Mainly for testing:
        capture_output=capture_output,
        text=capture_output if capture_output else None,
    )


